EXAMPLES=[{'id':'we-5-source-6','num':'6','title':'Example 6','problem':'For what t is G⃗(t) = |t|î + (cos t)ĵ + (t−5)k̂ differentiable?','given':'One absolute-value component and two smooth components.','method':'Differentiate each component and compare left/right derivatives at 0.','steps':['Cos t is differentiable everywhere with derivative −sin t.','The linear component t−5 is differentiable everywhere with derivative 1.','For t > 0, |t| = t, so its derivative is 1.','For t < 0, |t| = −t, so its derivative is −1.','At 0, the right difference quotient is 1 and the left difference quotient is −1.','The unequal component limits prevent a vector derivative at 0, although the vector is continuous there.','Thus G⃗′(t) = (sgn t)î − sin tĵ + k̂ for t ≠ 0.'],'answer':'Differentiable exactly for t ≠ 0.','progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':135,'verification':'JPG and full PDF checked'}]}, {'id':'we-5-source-7','num':'7','title':'Example 7','problem':'Differentiate F⃗(t) = eᵗî + sin tĵ + (t³+5t)k̂.','given':'Three differentiable scalar components.','method':'Use the component derivative theorem.','steps':['Every component is defined and differentiable for all real t.','The fixed basis vectors î,ĵ,k̂ do not depend on t.','Differentiate eᵗ: its derivative is eᵗ.','Differentiate sin t in radians: its derivative is cos t.','Differentiate t³+5t: the power and sum rules give 3t²+5.','Attach each derivative to its original basis vector.','Combine: F⃗′(t) = eᵗî + cos tĵ + (3t²+5)k̂, for all real t.'],'answer':'eᵗî + cos tĵ + (3t²+5)k̂.','progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':135,'verification':'JPG and full PDF checked'}]}]
